import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { installNativeBundles, prepareNativeBundle } from "../src/cli/connect/native-install.js";

const fault = vi.hoisted(() => ({ destination: "" }));
vi.mock("node:fs", async (original) => {
  const fs = await original<typeof import("node:fs")>();
  return { ...fs, renameSync: (source: string, destination: string) => {
    if (destination === fault.destination) throw new Error("Synthetic rename failure");
    return fs.renameSync(source, destination);
  } };
});

describe("native installation transaction", () => {
  let home: string;
  let source: string;
  let target: string;
  let config: string;
  beforeEach(() => {
    home = mkdtempSync(join(tmpdir(), "native-install-"));
    source = join(home, "source"); target = join(home, "installed"); config = join(home, "config.json");
    mkdirSync(source); writeFileSync(join(source, "plugin.mjs"), "version one");
    vi.stubEnv("HOME", home); vi.stubEnv("USERPROFILE", home);
    fault.destination = "";
  });
  afterEach(() => { fault.destination = ""; vi.unstubAllEnvs(); rmSync(home, { recursive: true, force: true }); });
  const plan = () => prepareNativeBundle(source, target, "test-plugin", ["plugin.mjs"], false);
  it("rolls back the installed bundle if activation fails and preserves config plus user files", () => {
    installNativeBundles([plan()], config, '{"version":1}\n');
    writeFileSync(join(target, "custom.txt"), "keep");
    writeFileSync(join(source, "plugin.mjs"), "version two");
    fault.destination = config;
    expect(() => installNativeBundles([plan()], config, '{"version":2}\n')).toThrow("Synthetic rename failure");
    expect(readFileSync(join(target, "plugin.mjs"), "utf8")).toBe("version one");
    expect(readFileSync(join(target, "custom.txt"), "utf8")).toBe("keep");
    expect(readFileSync(config, "utf8")).toBe('{"version":1}\n');
    expect(readdirSync(home).some((name) => name.includes(".stage-") || name.includes(".previous-"))).toBe(false);
  });
  it("removes new bundles when activating a fresh install fails", () => {
    fault.destination = config;
    expect(() => installNativeBundles([plan()], config, "{}\n")).toThrow("Synthetic rename failure");
    expect(existsSync(target)).toBe(false); expect(existsSync(config)).toBe(false);
  });
  it("removes obsolete managed files while retaining unknown user files", () => {
    writeFileSync(join(source, "old.mjs"), "old");
    installNativeBundles([plan()], config, "{}\n");
    writeFileSync(join(target, "custom.txt"), "keep");
    rmSync(join(source, "old.mjs"));
    installNativeBundles([plan()], config, "{}\n");
    expect(existsSync(join(target, "old.mjs"))).toBe(false);
    expect(readFileSync(join(target, "custom.txt"), "utf8")).toBe("keep");
  });
  it("reports recovery guidance for truncated manifests without changing installed files", () => {
    installNativeBundles([plan()], config, "{}\n");
    const manifest = join(target, ".agentmemory-install.json");
    writeFileSync(manifest, '{"files":');
    expect(plan).toThrow(/Invalid native install manifest.*restore its backup/);
    expect(readFileSync(manifest, "utf8")).toBe('{"files":');
    expect(readFileSync(join(target, "plugin.mjs"), "utf8")).toBe("version one");
    expect(readFileSync(config, "utf8")).toBe("{}\n");
  });
  it("rejects an install manifest that tries to remove files outside its bundle", () => {
    mkdirSync(target);
    writeFileSync(join(target, ".agentmemory-install.json"), JSON.stringify({ files: { "../config.json": "hash" } }));
    writeFileSync(config, "keep");
    expect(plan).toThrow("Invalid native install path");
    expect(readFileSync(config, "utf8")).toBe("keep");
  });
  it.skipIf(process.platform === "win32")("does not follow symbolic links in source or destination bundles", () => {
    symlinkSync(source, target, "dir");
    expect(plan).toThrow("symbolic links");
    rmSync(target); symlinkSync(config, join(source, "foreign"));
    expect(plan).toThrow("symbolic links");
  });
});

import { spawnSync } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import {
  III_INSTALL_CONNECT_TIMEOUT_S,
  III_INSTALL_MAX_TIME_S,
  III_RELEASE_SHA256,
  describeInstallFailure,
  expectedIiiSha256,
  iiiDownloadShellCommand,
  iiiManualInstallCommand,
  installIiiArchive,
  sha256File,
} from "../src/cli/engine-install.js";
import { III_PINNED_VERSION } from "../src/version.js";

const ASSET = "iii-x86_64-unknown-linux-gnu.tar.gz";
const sandboxes: string[] = [];

function sandbox(): string {
  const dir = mkdtempSync(join(tmpdir(), "agentmemory-install-"));
  sandboxes.push(dir);
  return dir;
}

afterEach(() => {
  for (const dir of sandboxes.splice(0)) rmSync(dir, { recursive: true, force: true });
});

function fakeCurl(dir: string, script: string): string {
  const bin = join(dir, "fakebin");
  mkdirSync(bin, { recursive: true });
  const path = join(bin, "curl");
  writeFileSync(path, `#!/bin/sh\n${script}\n`);
  chmodSync(path, 0o755);
  return bin;
}

function buildTarball(dir: string): string {
  const staging = join(dir, "staging");
  mkdirSync(staging);
  writeFileSync(join(staging, "iii"), "#!/bin/sh\necho iii\n");
  const tarball = join(dir, "iii.tar.gz");
  spawnSync("tar", ["-czf", tarball, "-C", staging, "iii"]);
  return tarball;
}

function curlServing(dir: string, tarball: string): string {
  return fakeCurl(
    dir,
    `out=""; while [ $# -gt 0 ]; do if [ "$1" = "-o" ]; then out="$2"; fi; shift; done; cp "${tarball}" "$out"`,
  );
}

function runInstall(dir: string, bin: string, sha256: string | null, asset = ASSET) {
  const binDir = join(dir, "bin");
  const binPath = join(binDir, "iii");
  const checksums = sha256 ? { "9.9.9": { [ASSET]: sha256 } } : {};
  const outcome = installIiiArchive({
    sh: "sh",
    releaseUrl: "https://example.invalid/iii.tar.gz",
    version: "9.9.9",
    asset,
    binDir,
    binPath,
    env: { ...process.env, PATH: `${bin}:${process.env.PATH}` },
    checksums,
  });
  return { outcome, binDir, binPath };
}

describe("iii engine auto-installer", () => {
  it("passes connect and overall timeouts to curl", () => {
    const cmd = iiiDownloadShellCommand();
    expect(cmd).toContain(`--connect-timeout ${III_INSTALL_CONNECT_TIMEOUT_S}`);
    expect(cmd).toContain(`--max-time ${III_INSTALL_MAX_TIME_S}`);
  });

  it("pins a SHA-256 for every auto-installable asset of the pinned engine release", () => {
    const pinned = III_RELEASE_SHA256[III_PINNED_VERSION];
    expect(pinned).toBeDefined();
    for (const asset of [
      "iii-aarch64-apple-darwin.tar.gz",
      "iii-x86_64-apple-darwin.tar.gz",
      "iii-x86_64-unknown-linux-gnu.tar.gz",
      "iii-aarch64-unknown-linux-gnu.tar.gz",
      "iii-armv7-unknown-linux-gnueabihf.tar.gz",
      "iii-x86_64-pc-windows-msvc.zip",
      "iii-aarch64-pc-windows-msvc.zip",
    ]) {
      expect(expectedIiiSha256(III_PINNED_VERSION, asset)).toMatch(/^[0-9a-f]{64}$/);
    }
  });

  it("leaves no partial binary or archive behind when the download times out", () => {
    const dir = sandbox();
    const bin = fakeCurl(
      dir,
      'out=""; while [ $# -gt 0 ]; do if [ "$1" = "-o" ]; then out="$2"; fi; shift; done; printf partial > "$out"; echo "curl: (28) Operation timed out" >&2; exit 28',
    );
    const { outcome, binDir, binPath } = runInstall(dir, bin, "0".repeat(64));

    expect(outcome.ok).toBe(false);
    if (!outcome.ok) {
      expect(outcome.reason).toBe("download");
      expect(outcome.detail).toContain("timed out");
    }
    expect(existsSync(binPath)).toBe(false);
    expect(readdirSync(binDir)).toEqual([]);
  });

  it("installs the binary when the download matches the pinned SHA-256", () => {
    const dir = sandbox();
    const tarball = buildTarball(dir);
    const { outcome, binDir, binPath } = runInstall(dir, curlServing(dir, tarball), sha256File(tarball));

    expect(outcome).toEqual({ ok: true });
    expect(existsSync(binPath)).toBe(true);
    expect(readdirSync(binDir)).toEqual(["iii"]);
  });

  it("refuses to extract a download whose SHA-256 does not match", () => {
    const dir = sandbox();
    const tarball = buildTarball(dir);
    const wrong = "f".repeat(64);
    const { outcome, binDir, binPath } = runInstall(dir, curlServing(dir, tarball), wrong);

    expect(outcome.ok).toBe(false);
    if (!outcome.ok) {
      expect(outcome.reason).toBe("checksum");
      expect(outcome.detail).toContain(`expected ${wrong}`);
      expect(outcome.detail).toContain(`got ${sha256File(tarball)}`);
    }
    expect(existsSync(binPath)).toBe(false);
    expect(readdirSync(binDir)).toEqual([]);
  });

  it("passes paths to the shell as arguments, never as script text", () => {
    const dir = sandbox();
    const tarball = buildTarball(dir);
    const tricky = join(dir, 'odd $(touch pwned) "dir"');
    const binPath = join(tricky, "iii");
    const outcome = installIiiArchive({
      sh: "sh",
      releaseUrl: "https://example.invalid/iii.tar.gz",
      version: "9.9.9",
      asset: ASSET,
      binDir: tricky,
      binPath,
      env: { ...process.env, PATH: `${curlServing(dir, tarball)}:${process.env.PATH}` },
      checksums: { "9.9.9": { [ASSET]: sha256File(tarball) } },
    });

    expect(outcome).toEqual({ ok: true });
    expect(existsSync(binPath)).toBe(true);
    expect(existsSync(join(process.cwd(), "pwned"))).toBe(false);
    expect(iiiDownloadShellCommand()).not.toContain(dir);
  });

  it("does not download anything for a platform or version without a pinned SHA-256", () => {
    const dir = sandbox();
    const bin = fakeCurl(dir, `touch "${join(dir, "curl-called")}"; exit 1`);
    const { outcome, binDir } = runInstall(dir, bin, null, "iii-riscv64-unknown-linux-gnu.tar.gz");

    expect(outcome.ok).toBe(false);
    if (!outcome.ok) expect(outcome.reason).toBe("no-checksum");
    expect(existsSync(join(dir, "curl-called"))).toBe(false);
    expect(existsSync(binDir)).toBe(false);
    expect(expectedIiiSha256(III_PINNED_VERSION, "iii-riscv64-unknown-linux-gnu.tar.gz")).toBeNull();
  });

  it("explains a timeout without stderr and prints a copyable manual command that verifies the archive", () => {
    expect(describeInstallFailure({ status: 28, stderr: "" })).toContain("download timed out");
    expect(
      describeInstallFailure({ status: null, error: Object.assign(new Error("x"), { code: "ETIMEDOUT" }) }),
    ).toContain("timed out after");
    const sha = "a".repeat(64);
    const manual = iiiManualInstallCommand("https://x/iii.tar.gz", "/b", "/b/iii", sha);
    expect(manual).toContain("curl -fL --connect-timeout");
    expect(manual).toContain('chmod +x "/b/iii"');
    expect(manual).toContain('mktemp "/b/.iii-download.XXXXXX"');
    expect(manual).not.toContain("/tmp/");
    expect(manual).toContain('rm -f "$archive"; (exit $code)');
    expect(manual).toContain(sha);
    expect(manual.indexOf(sha)).toBeLessThan(manual.indexOf("tar -xzf"));
    expect(iiiManualInstallCommand("https://x/iii.tar.gz", "/b", "/b/iii", null)).not.toContain("sha256sum");
  });

  it("the manual command stops before extraction when the checksum does not match", () => {
    const dir = sandbox();
    const tarball = buildTarball(dir);
    const bin = curlServing(dir, tarball);
    const binDir = join(dir, "manual");
    const binPath = join(binDir, "iii");
    const run = (sha: string) =>
      spawnSync("sh", ["-c", iiiManualInstallCommand("https://example.invalid/iii.tar.gz", binDir, binPath, sha)], {
        encoding: "utf-8",
        env: { ...process.env, PATH: `${bin}:${process.env.PATH}` },
      });

    expect(run("e".repeat(64)).status).not.toBe(0);
    expect(existsSync(binPath)).toBe(false);
    expect(run(sha256File(tarball)).status).toBe(0);
    expect(existsSync(binPath)).toBe(true);
  });
});

import { describe, it, expect, beforeEach, vi } from "vitest";

vi.mock("../src/logger.js", () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn() },
}));

import { registerActionsFunction } from "../src/functions/actions.js";
import type { Action, ActionEdge } from "../src/types.js";
import { mockKV, mockSdk } from "./helpers/mocks.js";

describe("Actions Functions", () => {
  let sdk: ReturnType<typeof mockSdk>;
  let kv: ReturnType<typeof mockKV>;

  beforeEach(() => {
    sdk = mockSdk();
    kv = mockKV();
    registerActionsFunction(sdk as never, kv as never);
  });

  describe("mem::action-create", () => {
    it("creates an action with valid data", async () => {
      const result = (await sdk.trigger("mem::action-create", {
        title: "Fix login bug",
        description: "Users cannot log in with SSO",
        priority: 7,
        createdBy: "agent-1",
        project: "webapp",
        tags: ["bug", "auth"],
      })) as { success: boolean; action: Action; edges: ActionEdge[] };

      expect(result.success).toBe(true);
      expect(result.action.id).toMatch(/^act_/);
      expect(result.action.title).toBe("Fix login bug");
      expect(result.action.description).toBe("Users cannot log in with SSO");
      expect(result.action.status).toBe("pending");
      expect(result.action.priority).toBe(7);
      expect(result.action.createdBy).toBe("agent-1");
      expect(result.action.project).toBe("webapp");
      expect(result.action.tags).toEqual(["bug", "auth"]);
      expect(result.action.createdAt).toBeDefined();
      expect(result.action.updatedAt).toBeDefined();
      expect(result.edges).toEqual([]);
    });

    it("returns error when title is missing", async () => {
      const result = (await sdk.trigger("mem::action-create", {
        description: "No title provided",
      })) as { success: boolean; error: string };

      expect(result.success).toBe(false);
      expect(result.error).toContain("title is required");
    });

    it("clamps priority 0 to default 5 (falsy fallback)", async () => {
      const result = (await sdk.trigger("mem::action-create", {
        title: "Zero priority task",
        priority: 0,
      })) as { success: boolean; action: Action };

      expect(result.success).toBe(true);
      expect(result.action.priority).toBe(5);
    });

    it("clamps negative priority to 1", async () => {
      const result = (await sdk.trigger("mem::action-create", {
        title: "Negative priority task",
        priority: -3,
      })) as { success: boolean; action: Action };

      expect(result.success).toBe(true);
      expect(result.action.priority).toBe(1);
    });

    it("clamps priority 15 to 10", async () => {
      const result = (await sdk.trigger("mem::action-create", {
        title: "High priority task",
        priority: 15,
      })) as { success: boolean; action: Action };

      expect(result.success).toBe(true);
      expect(result.action.priority).toBe(10);
    });

    it("validates parent action exists", async () => {
      const result = (await sdk.trigger("mem::action-create", {
        title: "Child task",
        parentId: "nonexistent_parent",
      })) as { success: boolean; error: string };

      expect(result.success).toBe(false);
      expect(result.error).toContain("parent action not found");
    });

    it("creates action with valid parent", async () => {
      const parentResult = (await sdk.trigger("mem::action-create", {
        title: "Parent task",
      })) as { success: boolean; action: Action };

      const childResult = (await sdk.trigger("mem::action-create", {
        title: "Child task",
        parentId: parentResult.action.id,
      })) as { success: boolean; action: Action };

      expect(childResult.success).toBe(true);
      expect(childResult.action.parentId).toBe(parentResult.action.id);
    });

    it("creates inline edges with valid types", async () => {
      const targetResult = (await sdk.trigger("mem::action-create", {
        title: "Target action",
      })) as { success: boolean; action: Action };

      const result = (await sdk.trigger("mem::action-create", {
        title: "Source action",
        edges: [
          { type: "requires", targetActionId: targetResult.action.id },
          { type: "unlocks", targetActionId: targetResult.action.id },
        ],
      })) as { success: boolean; action: Action; edges: ActionEdge[] };

      expect(result.success).toBe(true);
      expect(result.edges.length).toBe(2);
      expect(result.edges[0].id).toMatch(/^ae_/);
      expect(result.edges[0].type).toBe("requires");
      expect(result.edges[0].sourceActionId).toBe(result.action.id);
      expect(result.edges[0].targetActionId).toBe(targetResult.action.id);
      expect(result.edges[1].type).toBe("unlocks");
    });

    it("returns error for inline edge with invalid type", async () => {
      const targetResult = (await sdk.trigger("mem::action-create", {
        title: "Target action",
      })) as { success: boolean; action: Action };

      const result = (await sdk.trigger("mem::action-create", {
        title: "Source action",
        edges: [
          { type: "invalid_type", targetActionId: targetResult.action.id },
        ],
      })) as { success: boolean; error: string };

      expect(result.success).toBe(false);
      expect(result.error).toContain("invalid edge type");
    });

    it("returns error for inline edge with nonexistent target", async () => {
      const result = (await sdk.trigger("mem::action-create", {
        title: "Source action",
        edges: [{ type: "requires", targetActionId: "nonexistent_id" }],
      })) as { success: boolean; error: string };

      expect(result.success).toBe(false);
      expect(result.error).toContain("target action not found");
    });
  });

  describe("mem::action-update", () => {
    it("updates an action with valid data", async () => {
      const createResult = (await sdk.trigger("mem::action-create", {
        title: "Original title",
        priority: 5,
      })) as { success: boolean; action: Action };

      const updateResult = (await sdk.trigger("mem::action-update", {
        actionId: createResult.action.id,
        title: "Updated title",
        priority: 8,
        status: "active",
        assignedTo: "agent-2",
        tags: ["updated"],
      })) as { success: boolean; action: Action };

      expect(updateResult.success).toBe(true);
      expect(updateResult.action.title).toBe("Updated title");
      expect(updateResult.action.priority).toBe(8);
      expect(updateResult.action.status).toBe("active");
      expect(updateResult.action.assignedTo).toBe("agent-2");
      expect(updateResult.action.tags).toEqual(["updated"]);
    });

    it("returns error when actionId is missing", async () => {
      const result = (await sdk.trigger("mem::action-update", {
        title: "no id",
      })) as { success: boolean; error: string };

      expect(result.success).toBe(false);
      expect(result.error).toContain("actionId is required");
    });

    it("returns error for nonexistent action", async () => {
