import { describe, it, expect, afterEach, beforeEach } from "vitest";
import { resolveEnvOrEmpty } from "../src/mcp/rest-proxy.js";

const VAR = "AGENTMEMORY_TEST_URL";

describe("resolveEnvOrEmpty — guards against literal ${VAR} placeholders", () => {
  let original: string | undefined;

  beforeEach(() => {
    original = process.env[VAR];
    delete process.env[VAR];
  });

  afterEach(() => {
    if (original === undefined) delete process.env[VAR];
    else process.env[VAR] = original;
  });

  it("returns '' when env var is unset", () => {
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("returns '' when env var is empty string", () => {
    process.env[VAR] = "";
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("returns '' when env var is literal ${VAR} placeholder", () => {
    process.env[VAR] = "${AGENTMEMORY_TEST_URL}";
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("returns '' when env var is a different literal placeholder", () => {
    process.env[VAR] = "${SOME_OTHER_VAR}";
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("preserves a real URL value", () => {
    process.env[VAR] = "https://memory.prod.example/api";
    expect(resolveEnvOrEmpty(VAR)).toBe("https://memory.prod.example/api");
  });

  it("preserves a real secret value that happens to contain a $ char", () => {
    process.env[VAR] = "secret-with-$dollar";
    expect(resolveEnvOrEmpty(VAR)).toBe("secret-with-$dollar");
  });

  it("does not treat ${ at start without matching } as placeholder", () => {
    process.env[VAR] = "${unclosed";
    expect(resolveEnvOrEmpty(VAR)).toBe("${unclosed");
  });

  it("does not treat $VAR (no braces) as placeholder", () => {
    process.env[VAR] = "$AGENTMEMORY_URL";
    expect(resolveEnvOrEmpty(VAR)).toBe("$AGENTMEMORY_URL");
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";

const KEYS = [
  "OPENAI_API_KEY",
  "OPENAI_MODEL",
  "OPENAI_BASE_URL",
  "OPENROUTER_API_KEY",
  "OPENROUTER_MODEL",
  "OPENAI_API_KEY_FOR_LLM",
  "AGENTMEMORY_SUPPRESS_COST_WARNING",
];

async function warningsFor(env: Record<string, string>, loads = 1): Promise<string[]> {
  for (const [k, v] of Object.entries(env)) process.env[k] = v;
  const writes: string[] = [];
  vi.spyOn(process.stderr, "write").mockImplementation((chunk: string | Uint8Array) => {
    writes.push(String(chunk));
    return true;
  });
  vi.resetModules();
  const { loadConfig } = await import("../src/config.js");
  for (let i = 0; i < loads; i++) loadConfig();
  return writes.filter((w) => w.includes("premium tier"));
}

describe("premium-model cost warning", () => {
  beforeEach(() => {
    for (const k of KEYS) delete process.env[k];
  });
  afterEach(() => {
    for (const k of KEYS) delete process.env[k];
    vi.restoreAllMocks();
  });

  it("warns once for a premium OPENAI_MODEL, naming that variable", async () => {
    const warnings = await warningsFor(
      { OPENAI_API_KEY: "k", OPENAI_BASE_URL: "https://openrouter.ai/api/v1", OPENAI_MODEL: "anthropic/claude-sonnet-5" },
      2,
    );
    expect(warnings).toHaveLength(1);
    expect(warnings[0]).toContain("OPENAI_MODEL=anthropic/claude-sonnet-5 is in the premium tier");
  });

  it("stays quiet for the default and for cheap OpenAI-compatible models", async () => {
    expect(await warningsFor({ OPENAI_API_KEY: "k" })).toHaveLength(0);
    expect(await warningsFor({ OPENAI_API_KEY: "k", OPENAI_MODEL: "deepseek/deepseek-v4.1-flash:floor" })).toHaveLength(0);
  });

  it("is silenced by AGENTMEMORY_SUPPRESS_COST_WARNING", async () => {
    const warnings = await warningsFor({
      OPENAI_API_KEY: "k",
      OPENAI_MODEL: "gpt-4o",
      AGENTMEMORY_SUPPRESS_COST_WARNING: "1",
    });
    expect(warnings).toHaveLength(0);
  });

  it("keeps the OpenRouter warning text", async () => {
    const warnings = await warningsFor({
      OPENROUTER_API_KEY: "k",
      OPENROUTER_MODEL: "anthropic/claude-opus-5",
      OPENAI_API_KEY_FOR_LLM: "false",
    });
