}));

import { registerApiTriggers } from "../src/triggers/api.js";
import type { HttpRequest } from "@iii-dev/helpers/http";

function mockKV() {
  return {
    get: async () => null,
    set: async <T>(_s: string, _k: string, d: T) => d,
    delete: async () => {},
    update: async () => {},
    list: async <T>(): Promise<T[]> => [],
  };
}

function mockSdk() {
  const fns = new Map<string, (payload: unknown) => Promise<unknown>>();
  return {
    registerFunction: (id: string, h: (payload: unknown) => Promise<unknown>) =>
      fns.set(id, h),
    registerTrigger: () => {},
    trigger: async (input: { function_id: string; payload?: unknown }) =>
      fns.get(input.function_id)?.(input.payload),
    _fns: fns,
  };
}

async function callPatterns(
  sdk: ReturnType<typeof mockSdk>,
  body?: Record<string, unknown>,
): Promise<{ status_code: number; body: Record<string, unknown> }> {
  const handler = sdk._fns.get("api::patterns")!;
  return handler({
    headers: {},
    query_params: {},
    body,
  } as HttpRequest<Record<string, unknown>>) as Promise<{
    status_code: number;
    body: Record<string, unknown>;
  }>;
}

describe("api::patterns request hygiene", () => {
  it("defaults a bodyless request instead of throwing", async () => {
    const kv = mockKV();
    const sdk = mockSdk();
    let received: unknown;
    sdk.registerFunction("mem::patterns", async (payload) => {
      received = payload;
      return { patterns: [] };
    });
    registerApiTriggers(sdk as never, kv as never);

    const res = await callPatterns(sdk);

    expect(res.status_code).toBe(200);
    expect(received).toEqual({ project: undefined, limit: undefined });
  });

  it("whitelists the body to project and limit, dropping unexpected fields", async () => {
    const kv = mockKV();
    const sdk = mockSdk();
    let received: unknown;
    sdk.registerFunction("mem::patterns", async (payload) => {
      received = payload;
      return { patterns: [] };
    });
    registerApiTriggers(sdk as never, kv as never);

    await callPatterns(sdk, {
      project: "alpha",
      limit: 5,
      extra: "should not pass through",
    });

    expect(received).toEqual({ project: "alpha", limit: 5 });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { InMemoryKV } from "../src/mcp/in-memory-kv.js";
import { resetHandleForTests, setLivezProbe } from "../src/mcp/rest-proxy.js";

const originalUrl = "https://old-memory.example.invalid";
const changedUrl = "https://new-memory.example.invalid";

describe("MCP saves during proxy reconfiguration", () => {
  let home: string;

  beforeEach(() => {
    home = mkdtempSync(join(tmpdir(), "am-proxy-reconfiguration-"));
    vi.stubEnv("HOME", home);
    vi.stubEnv("USERPROFILE", home);
    vi.stubEnv("AGENTMEMORY_URL", originalUrl);
    vi.stubEnv("AGENTMEMORY_SECRET", "synthetic-proxy-secret");
    vi.stubEnv("AGENTMEMORY_FORCE_PROXY", "");
    resetHandleForTests();
  });

  afterEach(() => {
    resetHandleForTests();
    vi.unstubAllGlobals();
    vi.unstubAllEnvs();
    rmSync(home, { recursive: true, force: true });
  });

  it.each([
    { url: originalUrl, force: "1" },
    { url: changedUrl, force: "true" },
  ])("rejects saves instead of using pending local fallback after setting $force at $url", async ({ url, force }) => {
    const { handleToolCall } = await import("../src/mcp/standalone.js");
    const localKv = new InMemoryKV();
    let finishProbe!: (value: { ok: boolean }) => void;
    setLivezProbe(() => new Promise((resolve) => { finishProbe = resolve; }));
    const fetchMock = vi.fn(async (_url: string) => { throw new Error("synthetic backend unavailable"); });
    vi.stubGlobal("fetch", fetchMock);

    const waitingSave = handleToolCall("memory_save", { content: "Before reconfiguration" }, localKv);
    vi.stubEnv("AGENTMEMORY_URL", url);
    vi.stubEnv("AGENTMEMORY_FORCE_PROXY", force);
    const currentSave = handleToolCall("memory_save", { content: "After reconfiguration" }, localKv);
    const results = Promise.allSettled([waitingSave, currentSave]);
    finishProbe({ ok: false });

    for (const result of await results) {
      expect(result).toMatchObject({ status: "rejected", reason: { message: "synthetic backend unavailable" } });
    }
    expect(fetchMock).toHaveBeenCalledTimes(2);
    expect(fetchMock.mock.calls.map((call) => call[0])).toEqual([
      `${url}/agentmemory/remember`, `${url}/agentmemory/remember`,
    ]);
    expect(await localKv.list("mem:memories")).toEqual([]);
  });

  it("routes pending and new saves to the changed endpoint after an old probe fails", async () => {
    const { handleToolCall } = await import("../src/mcp/standalone.js");
    const localKv = new InMemoryKV();
    let finishProbe!: (value: { ok: boolean }) => void;
    const oldProbe = new Promise<{ ok: boolean }>((resolve) => { finishProbe = resolve; });
    setLivezProbe((url) => url === originalUrl ? oldProbe : Promise.resolve({ ok: true }));
    const fetchMock = vi.fn(async (_url: string) => new Response(JSON.stringify({ id: "remote-memory", action: "created" })));
    vi.stubGlobal("fetch", fetchMock);

    const waitingSave = handleToolCall("memory_save", { content: "Before endpoint change" }, localKv);
    vi.stubEnv("AGENTMEMORY_URL", changedUrl);
    const currentSave = handleToolCall("memory_save", { content: "After endpoint change" }, localKv);
    finishProbe({ ok: false });

    for (const result of await Promise.all([waitingSave, currentSave])) {
      expect(JSON.parse(result.content[0].text)).toEqual({ id: "remote-memory", action: "created" });
    }
    expect(fetchMock.mock.calls.map((call) => call[0])).toEqual([
      `${changedUrl}/agentmemory/remember`, `${changedUrl}/agentmemory/remember`,
    ]);
    expect(await localKv.list("mem:memories")).toEqual([]);
  });
});

import { describe, expect, it } from "vitest";
import { buildSyntheticCompression } from "../src/functions/compress-synthetic.js";
import { createObservationSource, OBSERVATION_SOURCE_MAX_BYTES, rawFromObservationSource } from "../src/functions/observation-source.js";
import { SearchIndex } from "../src/state/search-index.js";
import type { HookType, RawObservation } from "../src/types.js";

function raw(payload: unknown, fields: Partial<RawObservation> = {}): RawObservation {
  return { id: "custom-observation", sessionId: "custom-session", timestamp: "2026-01-01T00:00:00Z",
    hookType: "custom_event" as HookType, raw: payload, ...fields };
}

describe("custom payload synthetic search", () => {
  it("indexes retained payload content without inventing tool or prompt fields", () => {
    const original = raw({ title: "Quasar dispatch choice", content: "Use quasar routing for the job queue" });
    const observation = buildSyntheticCompression(original);
    const index = new SearchIndex();
    index.add(observation);
    expect(index.search("quasar").map((hit) => hit.obsId)).toContain(observation.id);
    expect(observation.narrative).toContain("Use quasar routing");
    expect(observation.source).toEqual(createObservationSource(original));
    expect(observation.source?.toolOutput).toBeUndefined();
    expect(rawFromObservationSource(observation)?.raw).toEqual(original.raw);
  });

  it.each(["message canary", ["message canary"], { nested: { message: "message canary" } }, 0, false])(
    "keeps supported primitive and structured payloads: %j", (payload) => {
      const observation = buildSyntheticCompression(raw(payload));
      const expected = typeof payload === "string" ? payload : JSON.stringify(payload);
      expect(observation.narrative).toBe(expected);
      expect(observation.source?.payload).toEqual(payload);
    },
  );

  it.each([undefined, null, {}, [], ""])("does not invent narrative for empty data: %j", (payload) => {
    expect(buildSyntheticCompression(raw(payload)).narrative).toBe("");
  });

  it("uses the sanitized source and never indexes private data or credentials", () => {
    const key = "sk-proj-abcdefghijklmnopqrstuvwxyz0123456789";
    const observation = buildSyntheticCompression(raw({ content: `Public canary <private>hidden-canary</private> ${key}` }));
    expect(observation.narrative).toContain("Public canary");
    expect(observation.narrative).toContain("[REDACTED]");
    expect(observation.narrative).not.toContain("hidden-canary");
    expect(observation.narrative).not.toContain(key);
  });

  it("preserves canonical prompt/tool precedence without duplicating envelope metadata", () => {
    const observation = buildSyntheticCompression(raw({ message: "envelope-only-canary" }, {
      userPrompt: "Prompt canary", toolInput: { command: "run" }, toolOutput: "Output canary",
    }));
    expect(observation.narrative).toBe('Prompt canary | {"command":"run"} | Output canary');
    expect(observation.source).not.toHaveProperty("payload");
  });

  it("bounds large Unicode data while leaving the retained source budget intact", () => {
    const original = raw("x".repeat(398) + "😀" + "界".repeat(20000));
    const observation = buildSyntheticCompression(original);
    expect(observation.narrative.length).toBeLessThanOrEqual(400);
    expect(observation.narrative).toBe("x".repeat(398) + "…");
    expect(observation.source).toEqual(createObservationSource(original));
    expect(observation.source?.truncated).toBe(true);
    expect(Buffer.byteLength(JSON.stringify(observation.source))).toBeLessThanOrEqual(OBSERVATION_SOURCE_MAX_BYTES);
  });
});

import { describe, it, expect, vi } from "vitest";
import { registerApiTriggers } from "../src/triggers/api.js";

type Handler = (req: unknown) => Promise<{ status_code: number; body: Record<string, unknown> }>;

function setup() {
  const kv = {
    get: vi.fn(async () => null),
    set: vi.fn(async (_scope: string, _key: string, value: unknown) => value),
    delete: vi.fn(async () => {}),
    list: vi.fn(async () => []),
  };
  const handlers = new Map<string, Handler>();
  const trigger = vi.fn(async (input: { function_id: string; payload: unknown }) => {
    if (input.function_id === "mem::lesson-save") return { success: true, action: "created", lesson: input.payload };
    return [];
  });
  const sdk = {
    registerFunction: (id: string, fn: Handler) => handlers.set(id, fn),
    registerTrigger: () => {},
    trigger,
    on: () => {},
  };
  registerApiTriggers(sdk as never, kv as never);
  const call = (id: string, req: { body?: unknown; query_params?: Record<string, string> }) =>
    handlers.get(id)!({ headers: {}, query_params: {}, body: {}, ...req });
  return { call, trigger };
}

describe("POST /agentmemory/lessons sourceIds", () => {
  it("stores validated sourceIds so a lesson can link to sessions and memories", async () => {
    const { call, trigger } = setup();
    const res = await call("api::lesson-save", {
      body: { content: "Snapshot RDS before upgrades", sourceIds: [" ses_infra_1 ", "mem_abc", "ses_infra_1"] },
    });
    expect(res.status_code).toBe(201);
    const payload = trigger.mock.calls[0][0].payload as Record<string, unknown>;
    expect(payload.sourceIds).toEqual(["ses_infra_1", "mem_abc"]);
    expect(payload.source).toBe("manual");
  });

  it("defaults to no sources and rejects malformed sourceIds", async () => {
    const { call, trigger } = setup();
    expect((await call("api::lesson-save", { body: { content: "No sources" } })).status_code).toBe(201);
    expect((trigger.mock.calls[0][0].payload as Record<string, unknown>).sourceIds).toEqual([]);

    for (const sourceIds of ["ses_1", [42], ["has space"], Array.from({ length: 51 }, (_, i) => `ses_${i}`)]) {
      const res = await call("api::lesson-save", { body: { content: "Bad", sourceIds } });
      expect(res.status_code).toBe(400);
    }
    expect(trigger).toHaveBeenCalledTimes(1);
  });
});

describe("GET /agentmemory/audit filters", () => {
  it("passes operation, date range and target text to the audit query", async () => {
    const { call, trigger } = setup();
    const res = await call("api::audit", {
      query_params: { operation: "forget", dateFrom: "2026-09-01", dateTo: "2026-09-30T23:59:59Z", q: "mem_", limit: "200" },
    });
    expect(res.status_code).toBe(200);
    expect(trigger.mock.calls[0][0]).toEqual({
      function_id: "mem::audit-query",
      payload: { operation: "forget", dateFrom: "2026-09-01", dateTo: "2026-09-30T23:59:59Z", query: "mem_", limit: 200 },
    });
  });

  it("rejects an invalid date", async () => {
    const { call, trigger } = setup();
    expect((await call("api::audit", { query_params: { dateFrom: "not-a-date" } })).status_code).toBe(400);
    expect(trigger).not.toHaveBeenCalled();
  });
});

import { describe, it, expect } from "vitest";
import { HybridSearch } from "../src/state/hybrid-search.js";
import { SearchIndex } from "../src/state/search-index.js";
import { VectorIndex } from "../src/state/vector-index.js";
import type { CompressedObservation } from "../src/types.js";

// Graph retrieval lists every node and edge on each search. A graph weight
// of 0 multiplied its results by zero but still paid for both traversals,
// so AGENTMEMORY_GRAPH_WEIGHT=0 saved nothing. At weight 0 the graph must
// not be read at all.

const obs: CompressedObservation = {
  id: "obs_1",
  sessionId: "ses_1",
  timestamp: new Date().toISOString(),
  type: "file_edit",
  title: "Edit auth middleware",
  subtitle: "JWT validation",
  facts: ["Added token check"],
  narrative:
    "Modified the AuthMiddleware in src/middleware/auth.ts to validate JWT tokens",
  concepts: ["authentication", "jwt"],
  files: ["src/middleware/auth.ts"],
  importance: 7,
};

function mockKV() {
  const store = new Map<string, Map<string, unknown>>();
  const listed: string[] = [];
  return {
    listed,
    get: async <T>(scope: string, key: string): Promise<T | null> =>
      (store.get(scope)?.get(key) as T) ?? null,
    set: async <T>(scope: string, key: string, data: T): Promise<T> => {
      if (!store.has(scope)) store.set(scope, new Map());
      store.get(scope)!.set(key, data);
      return data;
    },
    delete: async (scope: string, key: string): Promise<void> => {
      store.get(scope)?.delete(key);
    },
    list: async <T>(scope: string): Promise<T[]> => {
      listed.push(scope);
      const entries = store.get(scope);
      return entries ? (Array.from(entries.values()) as T[]) : [];
    },
  };
}

async function searchWith(graphWeight: number | undefined) {
  const bm25 = new SearchIndex();
  bm25.add(obs);
  const kv = mockKV();
  await kv.set("mem:obs:ses_1", "obs_1", obs);
  const hybrid =
    graphWeight === undefined
      ? new HybridSearch(bm25, null, null, kv as never)
      : new HybridSearch(bm25, null, null, kv as never, 0.4, 0.6, graphWeight);
  const results = await hybrid.search(
    "AuthMiddleware src/middleware/auth.ts JWT",
    10,
  );
  return {
    results,
    graphLists: kv.listed.filter((s) => s.startsWith("mem:graph:")),
  };
}

describe("graph weight 0 skips graph retrieval", () => {
  it("control: the default weight reads the graph", async () => {
    const { graphLists } = await searchWith(undefined);
    expect(graphLists.length).toBeGreaterThan(0);
  });

  it("weight 0 never lists a graph scope", async () => {
    const { graphLists } = await searchWith(0);
    expect(graphLists).toEqual([]);
  });

  it("weight 0 still returns the BM25 result", async () => {
    const { results } = await searchWith(0);
    expect(
      results.map((r) => r.observation?.id ?? (r as { obsId?: string }).obsId),
    ).toContain("obs_1");
  });
});

describe("graph weight 0 also skips vector-chunk graph expansion", () => {
  // Lowercase query with no entity-like tokens, so only the expansion
  // traversal (driven by the top vector hits) can read the graph.
  const embedder = {
    name: "fake",
    dimensions: 3,
    embed: async () => new Float32Array([1, 0, 0]),
    embedBatch: async (t: string[]) => t.map(() => new Float32Array([1, 0, 0])),
  };

  async function vectorSearchWith(graphWeight: number) {
    const bm25 = new SearchIndex();
    bm25.add(obs);
    const vector = new VectorIndex();
    vector.add("obs_1", "ses_1", new Float32Array([1, 0, 0]));
    const kv = mockKV();
    await kv.set("mem:obs:ses_1", "obs_1", obs);
    const hybrid = new HybridSearch(
      bm25,
      vector,
      embedder as never,
      kv as never,
      0.4,
      0.6,
      graphWeight,
    );
    await hybrid.search("validate tokens", 10);
    return kv.listed.filter((sc) => sc.startsWith("mem:graph:"));
  }

  it("control: a positive weight expands through the graph", async () => {
    expect((await vectorSearchWith(0.3)).length).toBeGreaterThan(0);
  });

  it("weight 0 does not expand through the graph", async () => {
    expect(await vectorSearchWith(0)).toEqual([]);
  });
});
